specs.contract:
admit(
  term(),
  keyword()
) :: {:ok, Wotex.Nx.Observation.t()} | {:error, Wotex.Lab.Error.t() | term()}

intent_from_proposal(
  Wotex.Nx.ActionProposal.t(),
  WotexContinuum.ExecutionScope.t(),
  DateTime.t(),
  keyword()
) :: {:ok, WotexContinuum.ActionIntent.t()} | {:error, WotexContinuum.Error.t()}

proposal_from_observation(
  Wotex.Nx.Observation.t(),
  WotexContinuum.ExecutionScope.t(),
  DateTime.t(),
  keyword()
) :: {:ok, WotexContinuum.ObservationProposal.t()} | {:error, WotexContinuum.Error.t()}

toolchain(module()) :: %{
  elixir: String.t(),
  otp: String.t(),
  backend: String.t(),
  platform: String.t()
}

snapshots(GenServer.server()) :: [
  %{
    snapshot: Wotex.Lab.Metrics.Snapshot.t(),
    gap: boolean(),
    reset: boolean(),
    clock_rollback: boolean()
  }
]

replay(
  Wotex.Lab.Runner.Recording.t(),
  Wotex.Lab.Runner.Definition.t(),
  Wotex.Lab.Runner.Host.t(),
  timeout()
) :: {:ok, %{comparison: term(), status: map()}} | {:error, Wotex.Lab.Error.t() | :timeout}
